<?php require_once __DIR__.'/_base.php'; $title='Provider Services'; include __DIR__.'/../includes/header.php'; ?><div class="dashboard-shell"><?php include __DIR__.'/../includes/sidebar.php'; ?><section class="content-area"><?php $pid=$pdo->query('SELECT id FROM providers WHERE user_id='.(int)$u['id'])->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$sid=(int)$_POST['service_id'];if($sid){$pdo->prepare('INSERT IGNORE INTO provider_services(provider_id,service_id) VALUES(?,?)')->execute([$pid,$sid]);}flash('success','Service added.');redirect('services.php');}$sv=$pdo->query("SELECT * FROM services WHERE status='Active' ORDER BY service_name")->fetchAll();$mine=$pdo->prepare('SELECT s.* FROM services s JOIN provider_services ps ON ps.service_id=s.id WHERE ps.provider_id=?');$mine->execute([$pid]);?><div class="row g-4"><div class="col-lg-5"><div class="service-card p-4"><h4>Add Service</h4><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><select name="service_id" class="form-select mb-3"><?php foreach($sv as $s):?><option value="<?=$s['id']?>"><?=e($s['service_name'])?></option><?php endforeach;?></select><button class="btn btn-success">Add</button></form></div></div><div class="col-lg-7"><div class="service-card p-4"><h4>My Services</h4><?php foreach($mine->fetchAll() as $s):?><span class="badge text-bg-light border me-2 mb-2 p-2"><?=e($s['service_name'])?></span><?php endforeach;?></div></div></div></section></div><?php include __DIR__.'/../includes/footer.php'; ?>